import random, subprocess, os, sys, json
from concurrent.futures import ThreadPoolExecutor
OPP=['stone','paper','vampire','snake','g2-clear']
TH={'stone':75,'paper':75,'vampire':75,'snake':33,'g2-clear':33}
def gen(rng):
    dual = rng.random()<0.6
    gateB = rng.choice([-2,-5,-10,-20,-50,-100,5,10])
    npad_before = rng.randint(0,6)
    bombA = rng.choice(['>2667','>1','0','<2667','>5335','#0','>3000'])
    splB = rng.choice(['0','0','<gate','>gate','<-500'])
    blocks=['L1']+(['L2'] if dual else [])+['B']
    rng.shuffle(blocks)
    # insert random pads between blocks
    lay=[]
    for b in blocks:
        lay += ['P']*rng.choice([0,0,0,1,2,3])
        lay.append(b)
    return dict(dual=dual,gateB=gateB,npad=npad_before,bombA=bombA,splB=splB,lay=lay)
def render(g):
    L=[';redcode-94',';name cand',';assert CORESIZE==8000',f'gate dat 0, {g["gateB"]}']
    L+=['     dat 0,0']*g['npad']
    if g['dual']: L.append('start spl c2')
    for b in g['lay']:
        if b=='P': L.append('     dat 0,0')
        elif b=='B': L.append(f'bomb dat {g["bombA"]}, 2-gate')
        else:
            n=b[1]
            L+= [f'c{n} spl #0, {g["splB"]}', f'l{n} mov bomb, >gate', f'   djn.f l{n}, >gate']
    if g['dual']: L.append('end start')
    else: L.append('end c1')
    return '\n'.join(L)+'\n'
def run(path,opp,r,fixed=False):
    cmd=['pmars','-b','-r',str(r)]+(['-f'] if fixed else [])+[path,f'/app/warriors/{opp}.red']
    out=subprocess.run(cmd,capture_output=True,text=True).stdout.strip().split('\n')[-1].split()
    return int(out[1])*100//r
def evaluate(g,i,r=200,fixed=False):
    p=f'/tmp/s/c{i}.red'; open(p,'w').write(render(g))
    res={o:run(p,o,r,fixed) for o in OPP}
    score=min(res[o]-TH[o] for o in OPP)
    return score,res,g
if __name__=='__main__':
    seed=int(sys.argv[1]); N=int(sys.argv[2])
    rng=random.Random(seed)
    gs=[gen(rng) for _ in range(N)]
    with ThreadPoolExecutor(16) as ex:
        results=list(ex.map(lambda a: evaluate(a[1],f'{seed}_{a[0]}'), enumerate(gs)))
    results.sort(key=lambda x:-x[0])
    for s,res,g in results[:10]:
        print(s,res,json.dumps(g))
EOF
